:root {
  --mask-image: url("data:image/png;base64,");
  --page-image-mask: url("data:image/png;base64,");
}

  @font-face {
    font-family: "BalooRegular";
    src: url("../../fonts/Baloo Regular 400.ttf") format("truetype");
    font-weight: 400;
    font-style: normal;
    font-display: swap;
  }

  @font-face {
    font-family: "LibreCaslon";
    src: url("../../fonts/LibreCaslonDisplay-Regular.ttf") format("truetype");
    font-weight: 400;
    font-style: normal;
  }

@font-face {
  font-family: "ITFDevanagari";
  src: url("../../fonts/ITFDevanagari-Bold.otf") format("opentype");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NotoSansGujaratiBold";
  src: url("../../fonts/NotoSansGujarati-Bold.ttf") format("truetype");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}


  *,
  *::before,
  *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html,
  body {
    margin: 0;
    padding: 0;
    width: 100%;
    height: 100%;
  }

  body {
    width: 100vw !important;
    height: 100%;
    background-image: url("../images/bg-image.png");
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center;
    background-attachment: fixed;
    overflow-x: hidden;
    opacity: 1;
    transition: opacity 0.5s ease;
  }


  body[data-lang="hi"] {
  font-family: "ITFDevanagari"!important;
}

body[data-lang="gu"] {
  font-family: "NotoSansGujaratiBold"!important;
  font-weight: 700!important;
}

  .pranam-video{
    position: absolute;
    left: 50%;
    top: 48.6%;
    transform: translate(-50%,-50%);
    width: 28vw;
    height: 28vw;
    border-radius: 50%;
background-color: white;

 background-image: url("./../images/pranam-bg-1.png");
    background-position: center;
    background-repeat: no-repeat;
    background-size: cover;
    overflow: hidden;
  }

.pranam-video video {
    width: 90%;
    height: 85%;
    padding-top: 2vw;
    object-fit: cover;

    /* Very light feather on ALL edges */
    -webkit-mask-image:
        linear-gradient(
            to bottom,
            transparent 0%,
            rgba(0, 0, 0, 0.8) 2%,
            rgba(0, 0, 0, 0.95) 4%,
            black 6%,
            black 90%,
            rgba(0, 0, 0, 0.95) 96%,
            rgba(0, 0, 0, 0.8) 98%,
            transparent 100%
        ),
        linear-gradient(
            to right,
            transparent 0%,
            rgba(0, 0, 0, 0.8) 2%,
            rgba(0, 0, 0, 0.95) 4%,
            black 6%,
            black 90%,
            rgba(0, 0, 0, 0.95) 96%,
            rgba(0, 0, 0, 0.8) 98%,
            transparent 100%
        );

    -webkit-mask-composite: source-in;

    mask-image:
        linear-gradient(
            to bottom,
            transparent 0%,
            rgba(0, 0, 0, 0.8) 2%,
            rgba(0, 0, 0, 0.95) 4%,
            black 6%,
            black 90%,
            rgba(0, 0, 0, 0.95) 96%,
            rgba(0, 0, 0, 0.8) 98%,
            transparent 100%
        ),
        linear-gradient(
            to right,
            transparent 0%,
            rgba(0, 0, 0, 0.8) 2%,
            rgba(0, 0, 0, 0.95) 4%,
            black 6%,
            black 90%,
            rgba(0, 0, 0, 0.95) 96%,
            rgba(0, 0, 0, 0.8) 98%,
            transparent 100%
        );

    mask-composite: intersect;

    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;

    -webkit-mask-size: 100% 100%;
    mask-size: 100% 100%;
}

  .home-btn {
    position: fixed;
    top: 2.5vw;
    left: 4%;
    width: 3.5vw;
    z-index: 1000;
    transition: transform 0.2s ease;
    cursor: pointer;
  }

  .home-btn:hover {
    transform: scale(1.15);
  }

  .home-btn img {
    width: 100%;
    display: block;
  }


  .language-container {
    position: fixed;
    top: 3.5vw;
    right: 5%;
    display: flex;
    width: 9vw;
    padding: 0.2vw 0.3vw;
    height: auto;
    justify-content: space-between;
    align-items: center;
    font-family: "BalooRegular";
    border: 0.2vw solid white;
    background-color: transparent;
    border-radius: 50vw;
    pointer-events: auto;
    z-index: 1000;
  }

  .language-container div {
    width: 2.5vw;
    height: 2.5vw;
    font-size: 1.6vw;
    text-align: center;
    border: 0.2vw solid white;
    background: transparent !important;
    color: white;
    cursor: pointer;
    display: flex;
    justify-content: center;
    align-items: center;
    border-radius: 50%;
    font-family: "BalooRegular", sans-serif;
  }

  .language-container div:hover {
    background-color: #ffffff !important;
    color: #FF9D6B;
  }

  .language-container div.active {
    background-color: #ffffff !important;
    color: #FF9D6B;
  }

  .page-video-border {
    position: fixed;
    top: 50%;
    left: 50%;
    width: 60vw;
    height: 100%;
    transform: translate(-50%, -50%);
    z-index: 5;
    background: white;
    overflow: visible !important;
    -webkit-mask-image: var(--mask-image);
    mask-image: var(--mask-image);
    -webkit-mask-size: contain;
    mask-size: contain;
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    -webkit-mask-position: center;
    mask-position: center;
  }

  .page-video {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 99%;
    height: auto;
    transform: translate(-50%, -50%);
    /* overflow: hidden; */

    -webkit-mask-image: var(--mask-image);
    mask-image: var(--mask-image);
    -webkit-mask-size: contain;
    mask-size: contain;
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    -webkit-mask-position: center;
    mask-position: center;
  }

  .page-video video {
    width: 100%;
    transform: scale(1.5);
    object-fit: cover;
    object-position: center center;
    display: block;
  }

  .page-image {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 99%;
    height: auto;
    transform: translate(-50%, -50%);
    /* overflow: hidden; */

    -webkit-mask-image: var(--page-image-mask);
    mask-image: var(--page-image-mask);
    -webkit-mask-size: contain;
    mask-size: contain;
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    -webkit-mask-position: center;
    mask-position: center;
  }


  .page-image img {
    width: 100%;
    transform: scale(1.5);
    object-fit: cover;
    object-position: center center;
    display: block;
  }


  .click {
    opacity: 1;
    padding: 0.2vw 2vw;
    font-size: 2vw;
    z-index: 99999;
    color: #FFD57D;
    background-color: #81004D;
    border: 0.2vw solid white;
    border-radius: 3vw;
    font-family: "EgaleLake";
    cursor: pointer;
    transition: background-color 0.3s ease, color 0.3s ease;
  }

  .click:hover {
    background-color: #FFD57D !important;
    color: #4d0000 !important;

  }

  .page-title {
    position: absolute;
    top: 3vw;
    left: 50%;
    transform: translateX(-50%);
    width: fit-content;
    height: 5vw;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 0.5vw;
    opacity: 0;
    transition: opacity 0.6s ease;
  }

  .page-title.visible {
    opacity: 1;
  }

  .page-title span {
    font-family: "LibreCaslon";
    font-size: 3vw;
    color: white;
  }


body[data-lang="gu"] .page-title span {
  font-weight: lighter!important;
}

  .page-title img {
    width: 2vw;
    display: block;
    object-fit: contain;
  }

  /* ─── PAGE 1 CONTAINER ─── */
  .page-1 {
    position: relative !important;
    width: 80vw;
    height: 80%;
    display: block;
    margin: 0 auto;
    margin-top: 9vw;
  }

  /* ─── ARCS — initial state: all stacked at arc-6 centre, invisible ─── */
  .page-1 .arc {
    position: absolute;
    width: 8vw;
    left: 50% !important;
    bottom: 5.6vw !important;
    transform: translateX(-50%) rotate(0deg) !important;
    opacity: 0;
    transition:
      left 0.9s cubic-bezier(0.25, 0.8, 0.25, 1),
      bottom 0.9s cubic-bezier(0.25, 0.8, 0.25, 1),
      transform 0.9s cubic-bezier(0.25, 0.8, 0.25, 1),
      opacity 0.5s ease;
  }

  /* ─── ARCS — animated (final) positions ─── */
  .page-1.arcs-ready .arc {
    opacity: 1;
  }

  .page-1.arcs-ready .arc-1 {
    left: 31% !important;
    bottom: -8vw !important;
    transform: translateX(-50%) rotate(-100deg) !important;
  }

  .page-1.arcs-ready .arc-2 {
    left: 32% !important;
    bottom: -3vw !important;
    transform: translateX(-50%) rotate(-80deg) !important;
  }

  .page-1.arcs-ready .arc-3 {
    left: 35% !important;
    bottom: 2vw !important;
    transform: translateX(-50%) rotate(-60deg) !important;
  }

  .page-1.arcs-ready .arc-4 {
    left: 40% !important;
    bottom: 6vw !important;
    transform: translateX(-50%) rotate(-40deg) !important;
  }

  .page-1.arcs-ready .arc-5 {
    left: 45.5% !important;
    bottom: 7vw !important;
    transform: translateX(-50%) rotate(-20deg) !important;
  }

  .page-1.arcs-ready .arc-6 {
    left: 50% !important;
    bottom: 7vw !important;
    transform: translateX(-50%) rotate(0deg) !important;
  }

  .page-1.arcs-ready .arc-7 {
    left: 54.5% !important;
    bottom: 7vw !important;
    transform: translateX(-50%) rotate(20deg) !important;
  }

  .page-1.arcs-ready .arc-8 {
    left: 60% !important;
    bottom: 6vw !important;
    transform: translateX(-50%) rotate(40deg) !important;
  }

  .page-1.arcs-ready .arc-9 {
    left: 65% !important;
    bottom: 2vw !important;
    transform: translateX(-50%) rotate(60deg) !important;
  }

  .page-1.arcs-ready .arc-10 {
    left: 67% !important;
    bottom: -3vw !important;
    transform: translateX(-50%) rotate(80deg) !important;
  }

  .page-1.arcs-ready .arc-11 {
    left: 69% !important;
    bottom: -8vw !important;
    transform: translateX(-50%) rotate(100deg) !important;
  }

  /* ─── MASCOT — starts at bottom:2vw, rises to 3vw in sync with arc transition ─── */
  .mascot {
    position: absolute;
    left: 50%;
    transform: translateX(-50%);
    width: 25vw;
    bottom: 2vw;
    z-index: 1000;
    transition: bottom 2s cubic-bezier(0.25, 0.8, 0.25, 1);
  }

  .mascot.lifted {
    bottom: 3vw;
  }

  .mascot img {
    width: 100%;
    display: block;
    object-fit: contain;
  }

  /* ─── ENTER BUTTON — starts hidden & shifted down ─── */
  .enter-btn {
    position: absolute;
    bottom: 2vw;
    left: 50%;
    transform: translateX(-50%) translateY(6vw);
    padding: 0.1vw 2.5vw;
    text-align: center;
    font-size: 1.5vw;
    font-family: "BalooRegular";
    background-image: linear-gradient(to bottom,
        #ede2ff 0%,
        #bd8eff 25%,
        #bd8eff 100%);
    color: white;
    border: 0.2vw solid white;
    border-radius: 3vw;
    z-index: 2000;
    opacity: 0;
    transition:
      opacity 0.5s ease,
      transform 0.65s cubic-bezier(0.34, 1.56, 0.64, 1),
      background-image 0.3s ease,
      color 0.3s ease;
    cursor: pointer;
  }

  .enter-btn.visible {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
  }

  .enter-btn:hover {
    background-image: linear-gradient(to bottom,
        #ffffff 0%,
        #d3b1ff 25%,
        #d3b1ff 100%);
    color: #4f4f4f;
  }

  /* ─── HOME BTN & LANGUAGE CONTAINER — stay hidden on load ─── */
  .home-button {
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.5s ease;
  }

  .home-button.revealed {
    opacity: 1;
    pointer-events: auto;
  }

  .page-2 {
    position: absolute;
    width: 95vw;
    height: 40vw;
    left: 50%;
    transform: translateX(-50%);
    bottom: 0vw;
    overflow: hidden;
  }

  .page-2 .t-container {
    width: 100%;
    object-fit: contain;
    display: block;
    position: relative !important;
    margin: 0 auto;
  }

  /* ── Topic wrapper: relative so spans overlay the img inside ── */
  .topic {
    z-index: 1000;
    position: absolute;
    width: 23vw;
    display: flex;
    justify-content: center;
    align-items: center;
  }

  /* ── Inner wrapper sits inside .topic, fills it, and is the
             positioning parent for both the img and the spans ── */
  .topic .topic-inner {
    position: relative;
    width: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
  }

  .topic img {
    width: 100%;
    display: block;
    object-fit: contain;
    transform: scale(1);
    transition: tranfrom 0.2s ease-in;
  }

  .topic:hover img {
    content: url("../images/t-hover-img.png");
    transform: scale(1.05);
  }

  /* Smaller image for topic-1, 2, 4, 5 */
  .topic-1 .topic-inner img,
  .topic-5 .topic-inner img,
  .topic-2 .topic-inner img,
  .topic-4 .topic-inner img {
    width: 75%;
  }

  /* ── Spans sit absolutely over the image ── */
  .topic .num,
  .topic .text {
    position: absolute;
    left: 50%;
    transform: translateX(-50%);
    text-align: center;
    pointer-events: none;
    font-family: "BalooRegular";
  
    color: white;
    text-shadow: -0.1vw 0.1vw 0.2vw rgba(0, 0, 0, 0.4);
  }

  /* Adjust these top values to taste — they sit over the img */
  .topic .num {
    top: 12%;
      font-size: 1.7vw !important;
  }

  .topic .text {
    width: 50%;
    height: 50%;
    word-wrap: break-word;
    top: 25%;
    display: flex;
    justify-content: center;
    align-items: center;
    text-align: center;
    line-height: 1.3;
      font-size: 1.5vw !important;
  }


  body[data-lang="hi"]  .topic .text {

}

body[data-lang="gu"]  .topic .text {
font-size: 1.4vw !important;
line-height: 2.3vw;
}

  /* ── Individual topic positions (unchanged) ── */
  .topic-1 {
    left: 7%;
    top: 58%;
  }

  .topic-5 {
    right: 7%;
    top: 58%;
  }

  .topic-2 {
    left: 19%;
    top: 28%;
  }

  .topic-4 {
    right: 19%;
    top: 28%;
  }

  .topic-3 {
    top: 9%;
    left: 50%;
    transform: translateX(-50%);
  }







