  .back-btn {
    position: absolute;
    left: 4%;
    top: 4%;
    width: 3vw;
    height: 3vw;
    background-color: white;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
    text-decoration: none;
    transform: scale(1);
    transition: transform 0.3s ease;
    z-index: 50;
  }

  .back-btn i {
    color: #8D59FF;
    font-size: 1vw;
    transition: font-size 0.3s ease;
  }

  .back-btn:hover {
    transform: scale(1.05);
    background-color: #8D59FF;
  }

  .back-btn:hover i {
    font-size: 1.2vw;
    color: white !important;
  }